/* Small, verified settings exports. Only known Verdant settings can restore. */
#include <time.h>
static const char *vf_settings_names[]={"preferences.cfg","engine.cfg","update-auto.cfg"};
static bool vf_digest_file(const char *path,uint32_t *hash,size_t *size){FILE *f=fopen(path,"rb");if(!f)return false;uint32_t h=2166136261u;size_t length=0;unsigned char data[1024];size_t n;while((n=fread(data,1,sizeof(data),f))){length+=n;for(size_t i=0;i<n;i++)h=(h^data[i])*16777619u;}bool ok=!ferror(f);fclose(f);*hash=h;*size=length;return ok;}
static bool vf_copy_small(const char *source,const char *dest){FILE *in=fopen(source,"rb"),*out=in?fopen(dest,"wb"):NULL;bool ok=in&&out;unsigned char data[1024];size_t n;if(ok){while((n=fread(data,1,sizeof(data),in)))if(fwrite(data,1,n,out)!=n){ok=false;break;}if(ferror(in)||fflush(out))ok=false;}if(in)fclose(in);if(out&&fclose(out))ok=false;if(!ok)remove(dest);return ok;}
static bool vf_settings_backup(char *response,size_t limit){mkdir(PLAT_SD "verdant/backups",0777);char folder[256],manifest[300],latest[256];bool made=false;for(int i=0;i<100;i++){snprintf(folder,sizeof(folder),PLAT_SD "verdant/backups/settings-%llu-%d",(unsigned long long)time(NULL),i);if(!mkdir(folder,0777)){made=true;break;}if(errno!=EEXIST)break;}if(!made){snprintf(response,limit,"Could not create settings backup");return false;}snprintf(manifest,sizeof(manifest),"%s/manifest.part",folder);FILE *m=fopen(manifest,"wb");if(!m)return false;bool ok=true;int count=0;for(int i=0;i<3&&ok;i++){char src[256],dest[300];snprintf(src,sizeof(src),PLAT_SD "verdant/%s",vf_settings_names[i]);struct stat st;if(stat(src,&st)){if(errno==ENOENT)continue;ok=false;break;}if(!S_ISREG(st.st_mode)||st.st_size>15000){ok=false;break;}snprintf(dest,sizeof(dest),"%s/%s",folder,vf_settings_names[i]);uint32_t a,b;size_t as,bs;ok=vf_copy_small(src,dest)&&vf_digest_file(src,&a,&as)&&vf_digest_file(dest,&b,&bs)&&a==b&&as==bs;if(ok){fprintf(m,"%d %u %zu\n",i,a,as);count++;}}if(fclose(m))ok=false;char done[300];snprintf(done,sizeof(done),"%s/manifest.txt",folder);if(!ok||!count||rename(manifest,done)){snprintf(response,limit,"Backup incomplete; existing backups remain available");return false;}snprintf(latest,sizeof(latest),PLAT_SD "verdant/backups/latest-settings.txt");FILE *f=fopen(latest,"wb");if(!f)return false;fprintf(f,"%s\n",strrchr(folder,'/')+1);ok=!ferror(f);if(fclose(f))ok=false;snprintf(response,limit,"Settings exported to %s. Restore applies on next launch.",folder);return ok;}
static bool vf_settings_restore(char *response,size_t limit){char pointer[256],name[100],folder[256],manifest[300];snprintf(pointer,sizeof(pointer),PLAT_SD "verdant/backups/latest-settings.txt");FILE *f=fopen(pointer,"rb");if(!f){snprintf(response,limit,"No completed settings backup");return false;}bool ok=fgets(name,sizeof(name),f)!=NULL;fclose(f);name[strcspn(name,"\r\n")]=0;if(!ok||strncmp(name,"settings-",9)||strspn(name,"settings-0123456789")!=strlen(name)){snprintf(response,limit,"Invalid backup folder name");return false;}snprintf(folder,sizeof(folder),PLAT_SD "verdant/backups/%s",name);snprintf(manifest,sizeof(manifest),"%s/manifest.txt",folder);f=fopen(manifest,"rb");if(!f)return false;char *contents[3]={0};bool seen[3]={0};int count=0,index;unsigned expected;size_t length;ok=true;while(fscanf(f,"%d %u %zu",&index,&expected,&length)==3){if(index<0||index>=3||seen[index]||length>15000){ok=false;break;}seen[index]=true;char path[300];snprintf(path,sizeof(path),"%s/%s",folder,vf_settings_names[index]);uint32_t actual;size_t bytes;if(!vf_digest_file(path,&actual,&bytes)||expected!=actual||bytes!=length){ok=false;break;}contents[index]=malloc(length+1);FILE *in=contents[index]?fopen(path,"rb"):NULL;if(!in){ok=false;break;}ok=fread(contents[index],1,length,in)==length;contents[index][length]=0;fclose(in);if(memchr(contents[index],0,length))ok=false;count++;}if(!feof(f))ok=false;fclose(f);
 if(ok&&count){for(int i=0;i<3&&ok;i++)if(contents[i]){char path[256],message[256];snprintf(path,sizeof(path),"/mnt/vita/ux0/verdant/%s",vf_settings_names[i]);ok=vf_execute("write",path,contents[i],message,sizeof(message));if(!ok)snprintf(response,limit,"Restore stopped: %s",message);}}else {ok=false;snprintf(response,limit,"Backup validation failed; settings unchanged");}for(int i=0;i<3;i++)free(contents[i]);if(ok)snprintf(response,limit,"Settings restored. Relaunch Verdant to apply.");return ok;}
/* Before each successful document save keep the previous contents separately. */
static bool vf_document_snapshot(const char *path){const char *rel=path+strlen(PLAT_SD);if(!strncmp(rel,"verdant/backups/",16)||!strcmp(rel,"verdant/preferences.cfg")||!strcmp(rel,"verdant/engine.cfg")||!strcmp(rel,"verdant/update-auto.cfg"))return true;struct stat st;if(stat(path,&st))return errno==ENOENT;if(!S_ISREG(st.st_mode))return false;mkdir(PLAT_SD "verdant/backups",0777);mkdir(PLAT_SD "verdant/backups/documents",0777);uint32_t key=2166136261u;for(const char *p=path;*p;p++)key=(key^(unsigned char)*p)*16777619u;char dest[300];for(int i=0;i<100;i++){snprintf(dest,sizeof(dest),PLAT_SD "verdant/backups/documents/%08x-%llu-%d.txt",key,(unsigned long long)time(NULL),i);if(stat(dest,&st)&&errno==ENOENT)break;if(i==99)return false;}if(!vf_copy_small(path,dest))return false;char origin[340];snprintf(origin,sizeof(origin),"%s.origin",dest);FILE *meta=fopen(origin,"wb");if(meta){fprintf(meta,"/mnt/vita/ux0/%s\n",rel);fclose(meta);}uint32_t a,b;size_t as,bs;return vf_digest_file(path,&a,&as)&&vf_digest_file(dest,&b,&bs)&&a==b&&as==bs;}
